/* ============================================
   iTVT - Optimized JavaScript
   Performance: RAF, passive listeners,
   IntersectionObserver, debouncing.
   ============================================ */

(function () {
  'use strict';

  // --- Utils ---
  const debounce = (fn, ms) => {
    let timer; return (...args) => { clearTimeout(timer); timer = setTimeout(() => fn(...args), ms); };
  };

  const qs = (s, ctx) => (ctx || document).querySelector(s);
  const qsa = (s, ctx) => (ctx || document).querySelectorAll(s);

  // --- Preloader ---
  (function preloader() {
    const preloader = qs('#preloader');
    if (!preloader) return;
    // Use requestAnimationFrame to remove preloader after paint
    const hide = () => {
      requestAnimationFrame(() => {
        preloader.classList.add('hidden');
        setTimeout(() => { preloader.style.display = 'none'; }, 600);
      });
    };
    // Wait for load, max 4s fallback
    let loaded = false;
    const onLoad = () => { if (!loaded) { loaded = true; hide(); } };
    window.addEventListener('load', onLoad, { once: true });
    setTimeout(() => { if (!loaded) { loaded = true; hide(); } }, 4000);
    // Also hide when DOM is ready if everything is already cached
    if (document.readyState === 'complete') { onLoad(); }
  })();

  // --- Typing Effect (optimized) ---
  (function typing() {
    const el = qs('.typing-text');
    if (!el) return;
    const text = el.textContent.trim();
    el.textContent = '';
    let index = 0;
    let rafId = null;
    let lastTime = 0;
    const speed = 50; // ms per char

    function typeChar(timestamp) {
      if (!lastTime) lastTime = timestamp;
      if (!text || index >= text.length) { el.textContent = text; return; }
      const elapsed = timestamp - lastTime;
      if (elapsed >= speed) {
        el.textContent += text[index];
        index++;
        lastTime = timestamp;
      }
      if (index < text.length) {
        rafId = requestAnimationFrame(typeChar);
      }
    }

    // Start typing when element is visible using IntersectionObserver
    if ('IntersectionObserver' in window) {
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            lastTime = 0;
            rafId = requestAnimationFrame(typeChar);
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.3 });
      observer.observe(el);
    } else {
      // Fallback
      const doType = () => { rafId = requestAnimationFrame(typeChar); };
      if (document.readyState === 'complete') { doType(); }
      else { window.addEventListener('load', doType, { once: true }); }
    }
  })();

  // --- Navbar scroll behavior ---
  (function navbarScroll() {
    const navbar = qs('#navbar');
    if (!navbar) return;
    let lastScroll = 0;
    let ticking = false;

    const onScroll = () => {
      const currentScroll = window.pageYOffset || document.documentElement.scrollTop;
      const heroHeight = window.innerHeight;

      if (currentScroll > heroHeight * 0.8) {
        navbar.classList.toggle('hidden-nav', currentScroll > lastScroll && currentScroll > 80);
      } else {
        navbar.classList.remove('hidden-nav');
      }
      lastScroll = currentScroll;
      ticking = false;
    };

    window.addEventListener('scroll', () => {
      if (!ticking) {
        requestAnimationFrame(onScroll);
        ticking = true;
      }
    }, { passive: true });
  })();

  // --- Mobile nav toggle ---
  (function mobileNav() {
    const toggle = qs('#navToggle');
    const menu = qs('#navMenu');
    if (!toggle || !menu) return;

    toggle.addEventListener('click', () => {
      toggle.classList.toggle('active');
      menu.classList.toggle('active');
    });

    // Close on link click
    qsa('.nav-link', menu).forEach(link => {
      link.addEventListener('click', () => {
        toggle.classList.remove('active');
        menu.classList.remove('active');
      });
    });
  })();

  // --- Active nav link (scroll spy) ---
  (function scrollSpy() {
    const links = qsa('.nav-link');
    if (!links.length) return;
    const sections = [];
    links.forEach(link => {
      const id = link.getAttribute('href');
      if (id && id.startsWith('#')) {
        const section = qs(id);
        if (section) sections.push({ link, section });
      }
    });
    if (!sections.length) return;

    let ticking = false;
    const onScroll = () => {
      const scrollY = window.pageYOffset || document.documentElement.scrollTop;
      let current = sections[0];
      for (const s of sections) {
        const rect = s.section.getBoundingClientRect();
        if (rect.top <= 200) current = s;
      }
      links.forEach(l => l.classList.remove('active'));
      if (current) current.link.classList.add('active');
      ticking = false;
    };

    window.addEventListener('scroll', () => {
      if (!ticking) { requestAnimationFrame(onScroll); ticking = true; }
    }, { passive: true });
  })();

  // --- Back to top ---
  (function backToTop() {
    const btn = qs('#backToTop');
    if (!btn) return;
    let ticking = false;

    const onScroll = () => {
      const scrollY = window.pageYOffset || document.documentElement.scrollTop;
      btn.classList.toggle('visible', scrollY > 400);
      ticking = false;
    };

    window.addEventListener('scroll', () => {
      if (!ticking) { requestAnimationFrame(onScroll); ticking = true; }
    }, { passive: true });

    btn.addEventListener('click', () => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  })();

  // --- Section reveal (lazy fade-in with IntersectionObserver) ---
  (function sectionReveal() {
    if (!('IntersectionObserver' in window)) return;
    const sections = qsa('.section');
    sections.forEach(s => s.style.opacity = '0');

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          requestAnimationFrame(() => {
            entry.target.style.transition = 'opacity 0.6s ease';
            entry.target.style.opacity = '1';
          });
          observer.unobserve(entry.target);
        }
      });
    }, { rootMargin: '0px 0px -100px 0px', threshold: 0.05 });

    sections.forEach(s => observer.observe(s));
  })();

  // --- Smooth anchor scroll (fallback for older browsers) ---
  (function anchorScroll() {
    document.addEventListener('click', (e) => {
      const link = e.target.closest('a[href^="#"]');
      if (!link) return;
      const id = link.getAttribute('href');
      if (!id || id === '#') return;
      const target = qs(id);
      if (!target) return;
      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, { passive: false });
  })();

})();
